        public void ExportExcelDailyWLDirectLC(string winlostdate, string reportTitle)
        {
            var _dailyWL = new ReportManager();
            var getReportData =
                  SessionExtension.GetSession(HttpContext.Current.Session, _dailyWL._keyDailyWLDirectLC) != null
                      ? (ListDailyWL)
                        SessionExtension.GetSession(HttpContext.Current.Session, _dailyWL._keyDailyWLDirectLC)
                      : _dailyWL.GetDailyWLDirectLC(winlostdate);
            #region excel format

            const int startCol = 0;
            const int startRow = 2;
            var nextRow = 0;
            var reportName = reportTitle.Replace(" ", "");
            var excelFile = new ExcelFile();
            var wsReport = excelFile.Worksheets.Add(reportName);

            #endregion
            #region header

            wsReport.Cells.GetSubrangeAbsolute(startRow - 2, startCol, startRow - 2, startCol + 6).Merged = true;
            wsReport.Cells.GetSubrangeAbsolute(startRow - 2, startCol, startRow - 2, startCol + 6).Style.Font.Weight = ExcelFont.BoldWeight;
            wsReport.Cells.GetSubrangeAbsolute(startRow - 2, startCol, startRow - 2, startCol + 6).Style.
                HorizontalAlignment = HorizontalAlignmentStyle.Center;
            wsReport.Cells.GetSubrangeAbsolute(startRow - 2, startCol, startRow - 2, startCol + 6).Value = reportTitle;
            Export2ExcelDailyWLDirectLiveCasinoHeader(ref wsReport, startRow, startCol);
            #endregion
            #region content
            if (getReportData != null)
            {

                Export2ExcelDailyWLDirectLiveCasinoContent(ref wsReport, startRow, startCol, ref nextRow,
                                                                     getReportData);
            }


            #endregion
            #region response file

            var response = HttpContext.Current.Response;
            response.Clear();
            response.ContentType = "application/vnd.ms-excel";
            response.AddHeader("Content-Disposition", String.Format("attachment; filename={0}.xls", reportName));
            excelFile.SaveXls(response.OutputStream);

            #endregion 


        }

