        #region Game statistics report
        public void ExportExcelGameStatisticsReport(GameStatisticsParams request)
        {
            #region get data
            request.pageindex = 0;
            request.pagesize = 0;
            request.movebetsday = ReportUtils.BalanceUp.MoveBetsDay.ToShortDateString();
            //request.fromcache = true;
            GameStatisticsBO reportData;
            if (request.fromcache)
            {
                reportData = SessionExtension.GetSession(HttpContext.Current.Session, GameStatisticMappedSessionKey) !=
                                  null
                                      ? (GameStatisticsBO)
                                        SessionExtension.GetSession(HttpContext.Current.Session,
                                                                    GameStatisticMappedSessionKey)
                                      : new ReportManager().GetGameStatisticsData(request);

            }
            else
            {
                reportData = new ReportManager().GetGameStatisticsData(request);
            }



            var startCol = 0;
            var startRow = 2;
            var reportName = "LiveCasinoGamStatistics";
            var excelFile = new ExcelFile();

            var maxItemsInSheet = 3000;
            #endregion

            if (reportData.Items != null && reportData.Items != null && reportData.Items.Count > 0)
            {
                #region filter by username
                if (request.reporttype == (int)FilterGameCondition.Username)
                {

                    ExportExcelGameStatisticsAssignContentByUsername(startRow, startCol, maxItemsInSheet, ref excelFile, reportData, request.showrefund);

                }
                #endregion
                #region filter by currency
                else if (request.reporttype == (int)FilterGameCondition.Currency)
                {
                    ExportExcelGameStatisticsAssignContentByCurrency(startRow, startCol, maxItemsInSheet, ref excelFile, reportData, request.showrefund);
                }
                #endregion
                #region other report type: Daily, Monthly, GameType, GameTable, Company
                else
                {
                    ExportExcelGameStatisticsAssignContentForEachGroupType(startRow, startCol, maxItemsInSheet, ref excelFile, reportData, request);
                }

                #endregion
            }
            else
            {
                var errorMsg = reportData.total == -100 ?
                    ResourceExtension.GetResourceValue(ResourceExtension.Resources.ErrorMsg, "TimeOutError") :
                    ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "lblThereisnodata");

                var wsReport =
                    excelFile.Worksheets.Add(string.Format("LiveCasinoGamStatistics"));
                wsReport.Cells[startRow - 1, startCol].Value = errorMsg;
            }

            #region response file
            var response = HttpContext.Current.Response;
            response.Clear();
            response.ContentType = "application/vnd.ms-excel";
            response.AddHeader("Content-Disposition", String.Format("attachment; filename={0}.xls", reportName));
            excelFile.SaveXls(response.OutputStream);

            #endregion
        }

