                var wsReport = excelFile.Worksheets.Add(string.Format("LiveCasinoGamStatistics_{0}", i + 1));
                #region header
                ExportExcelGameStatisticsAssignHeader(startRow, startCol, ref wsReport, (int)FilterGameCondition.Currency, isShowRefund);
                #endregion

                #region content

                var totalItemsInCurrentSheet = i < totalSheet - 1 ? maxItemsInSheet : (report.total - (i * maxItemsInSheet));
                for (int j = 0; j < totalItemsInCurrentSheet; j++)
                {
                    var item = report.Items[itemIndex];
                    var nextCol = 0;

                    wsReport.Cells[startRow + nextRow, startCol].Style = numberDefaultFormat;
                    wsReport.Cells[startRow + nextRow, startCol].Value = item.ReportType;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberDefaultFormat;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = item.NoPlayers;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberDefaultFormat;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = item.NoGames;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberFormat;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.TotalBets);
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberFormat;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.TotalWins);
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberFormat;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.GameIncome);
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = percentFormatTotal;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.GamePayout.Replace("%", "")) / 100;

