                    {
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberFormat;
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.TotalRefund);
                    }
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberFormat;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.CompanyTO);
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberFormat;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.CompanyComm);
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberFormat;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.Company);

                    nextRow++;
                    itemIndex++;
                }
                #endregion

                #region currency total & grand total
                if (i == totalSheet - 1 && report.TotalItems != null)
                {
                    var numberTotalDefaultFormat = new Sunplus.Accounting.Core.Helper.ExcelGemboxUtils().GetStyleIntNumber(".00", Color.FromArgb(247, 236, 201), true, false);
                    var numberTotalFormat = new Sunplus.Accounting.Core.Helper.ExcelGemboxUtils().GetStyleIntNumber(".00", Color.FromArgb(247, 236, 201), true, false, true);
                    var percentTotalFormatTotal = new Sunplus.Accounting.Core.Helper.ExcelGemboxUtils().GetStyleIntNumber(".00%", Color.FromArgb(247, 236, 201), true, false, true);
                    var numberGandTotalDefaultFormat = new Sunplus.Accounting.Core.Helper.ExcelGemboxUtils().GetStyleIntNumber(".00", Color.FromArgb(162, 212, 247), true, false);
                    var numberGandTotalFormat = new Sunplus.Accounting.Core.Helper.ExcelGemboxUtils().GetStyleIntNumber(".00", Color.FromArgb(162, 212, 247), true, false, true);
                    var percentGandTotalFormatTotal = new Sunplus.Accounting.Core.Helper.ExcelGemboxUtils().GetStyleIntNumber(".00%", Color.FromArgb(162, 212, 247), true, false, true);

                    #region total
                    foreach (var item in report.TotalItems)
                    {
                        var nextCol = 0;
                        wsReport.Cells[startRow + nextRow, startCol].Style = numberTotalDefaultFormat;
                        wsReport.Cells[startRow + nextRow, startCol].Value = item.ReportType;
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberTotalDefaultFormat;
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = item.NoPlayers;
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberTotalDefaultFormat;
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = item.NoGames;
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberTotalFormat;
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.TotalBets);
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberTotalFormat;
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.TotalWins);
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberTotalFormat;
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.GameIncome);
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = percentTotalFormatTotal;
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.GamePayout.Replace("%", "")) / 100;
                        if (isShowRefund)
                        {
                            wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberTotalFormat;
                            wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.TotalRefund);
                        }
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberTotalFormat;
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.CompanyTO);
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberTotalFormat;
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.CompanyComm);
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberTotalFormat;
                        wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = CastAide.AsDecimal(item.Company);

                        nextRow++;
                    }
                    #endregion

                    #region grand total

                    foreach (var grandTotalItem in report.GrandTotal)
                    {
                        var nextColGrandTotal = 0;
                        wsReport.Cells[startRow + nextRow, startCol].Style = numberGandTotalDefaultFormat;
                        wsReport.Cells[startRow + nextRow, startCol].Value = grandTotalItem.ReportType;
                        wsReport.Cells[startRow + nextRow, startCol + (nextColGrandTotal += 1)].Style = numberGandTotalDefaultFormat;
                        wsReport.Cells[startRow + nextRow, startCol + (nextColGrandTotal)].Value = grandTotalItem.NoPlayers;
                        wsReport.Cells[startRow + nextRow, startCol + (nextColGrandTotal += 1)].Style = numberGandTotalDefaultFormat;
                        wsReport.Cells[startRow + nextRow, startCol + (nextColGrandTotal)].Value = grandTotalItem.NoGames;
                        wsReport.Cells[startRow + nextRow, startCol + (nextColGrandTotal += 1)].Style = numberGandTotalFormat;
                        wsReport.Cells[startRow + nextRow, startCol + (nextColGrandTotal)].Value = CastAide.AsDecimal(grandTotalItem.TotalBets);
                        wsReport.Cells[startRow + nextRow, startCol + (nextColGrandTotal += 1)].Style = numberGandTotalFormat;
                        wsReport.Cells[startRow + nextRow, startCol + (nextColGrandTotal)].Value = CastAide.AsDecimal(grandTotalItem.TotalWins);
                        wsReport.Cells[startRow + nextRow, startCol + (nextColGrandTotal += 1)].Style = numberGandTotalFormat;
                        wsReport.Cells[startRow + nextRow, startCol + (nextColGrandTotal)].Value = CastAide.AsDecimal(grandTotalItem.GameIncome);
                        wsReport.Cells[startRow + nextRow, startCol + (nextColGrandTotal += 1)].Style = percentGandTotalFormatTotal;
                        wsReport.Cells[startRow + nextRow, startCol + (nextColGrandTotal)].Value = CastAide.AsDecimal(grandTotalItem.GamePayout.Replace("%", "")) / 100;
                        if (isShowRefund)
                        {
