                        wsReport.Cells[startRow + nextRow, startCol + (nextColGrandTotal += 1)].Style = numberGandTotalFormat;
                        wsReport.Cells[startRow + nextRow, startCol + (nextColGrandTotal)].Value = CastAide.AsDecimal(grandTotalItem.Company);
