        }
        private void ExportExcelGameStatisticsAssignContentForEachGroupType(int startRow, int startCol, int maxItemsInSheet, ref ExcelFile excelFile, GameStatisticsBO report, GameStatisticsParams pParams)
        {
            var numberDefaultFormat = new Sunplus.Accounting.Core.Helper.ExcelGemboxUtils().GetStyleIntNumber(".00", Color.FromArgb(253, 252, 252), false, false);
            var numberFormat = new Sunplus.Accounting.Core.Helper.ExcelGemboxUtils().GetStyleIntNumber(".00", Color.FromArgb(253, 252, 252), false, false, true);
            var percentFormatTotal = new Sunplus.Accounting.Core.Helper.ExcelGemboxUtils().GetStyleIntNumber(".00%", Color.FromArgb(253, 252, 252), false, false, true);
            var nextRow = 0;
            var currentSheet = 1;
            var isShowRefund = pParams.showrefund;
            #region content

            ExcelWorksheet wsReport = null;
            foreach (var group in report.Items)
            {
                #region create header for each sheet
                if (group.Items.Count + nextRow + startRow > maxItemsInSheet | currentSheet == 1)
                {
                    nextRow = 0;
                    wsReport = excelFile.Worksheets.Add(string.Format("LiveCasinoGamStatistics_{0}", currentSheet));
                    #region header
                    ExportExcelGameStatisticsAssignHeader(startRow, startCol, ref wsReport, pParams.reporttype, isShowRefund);
                    #endregion

                    currentSheet++;
                }
                #endregion

                #region detail

                var isFirstRow = true;
                foreach (var item in group.Items)
                {
                    var nextCol = 0;
                    if (isFirstRow)
                    {
                        wsReport.Cells.GetSubrangeAbsolute(startRow + nextRow, startCol,
                                                           startRow + nextRow + (group.Items.Count - 1), startCol).Merged = true;
                        wsReport.Cells.GetSubrangeAbsolute(startRow + nextRow, startCol,
                                                           startRow + nextRow + (group.Items.Count - 1), startCol).Style
                            = numberDefaultFormat;
                        wsReport.Cells.GetSubrangeAbsolute(startRow + nextRow, startCol,
                                                           startRow + nextRow + (group.Items.Count - 1), startCol).Value
                            = item.ReportType;
                    }


                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberDefaultFormat;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = item.NoPlayers;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = numberDefaultFormat;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol)].Value = item.NoGames;
